const key='pino-workforce-v2-config';let data=JSON.parse(localStorage.getItem(key)||'null')||{weeks:[{from:'2026-10-12',to:'2026-10-18',registration:false,assignment:true,final:false}],templates:[{code:'EVENING',name:'Ca tối',start:'18:00',end:'21:00',active:true},{code:'MORNING',name:'Ca sáng',start:'08:00',end:'12:00',active:true}]};let edit=-1;function persist(){localStorage.setItem(key,JSON.stringify(data))}function tab(n){document.getElementById('weeks').classList.toggle('hidden',n!==0);document.getElementById('templates').classList.toggle('hidden',n!==1)}function renderWeeks(){const s=document.getElementById('week');s.innerHTML=data.weeks.map((w,i)=>'<option value="'+i+'">'+w.from+' → '+w.to+'</option>').join('');renderStatus()}function current(){return data.weeks[+document.getElementById('week').value||0]}function renderStatus(){let w=current();document.getElementById('status').textContent='Staff: '+(w.registration?'OPEN':'LOCKED')+' · Manager: '+(w.assignment?'OPEN':'LOCKED')+' · '+(w.final?'Đã chốt':'Chưa chốt')+(w.until?' · Mở lại đến '+w.until:'')}function addWeek(){let from=document.getElementById('from').value,to=document.getElementById('to').value;if(!from||!to||to<from)return alert('Khoảng ngày không hợp lệ');if(data.weeks.some(w=>w.from===from))return alert('Tuần đã tồn tại');data.weeks.push({from,to,registration:true,assignment:true,final:false});persist();renderWeeks();document.getElementById('week').value=data.weeks.length-1;renderStatus()}function toggle(k){let w=current(),reason=document.getElementById('reason').value.trim();if(!reason)return alert('Cần nhập lý do thay đổi');w[k]=!w[k];w.reason=reason;w.until=document.getElementById('until').value;if(k==='final')w.assignment=!w.final;persist();renderStatus()}function renderTemplates(){document.getElementById('list').innerHTML=data.templates.map((t,i)=>'<div class="card"><strong>'+t.name+'</strong> · '+t.code+' · '+t.start+'–'+t.end+' · '+(t.active?'ACTIVE':'INACTIVE')+' <button onclick="editTemplate('+i+')">Sửa</button><button onclick="activate('+i+')">'+(t.active?'Ngừng':'Kích hoạt')+'</button></div>').join('')}function editTemplate(i){edit=i;let t=data.templates[i];['code','name','start','end'].forEach(k=>document.getElementById(k).value=t[k]);scrollTo(0,0)}function activate(i){data.templates[i].active=!data.templates[i].active;persist();renderTemplates()}function saveTemplate(){let t={};for(let k of ['code','name','start','end'])t[k]=document.getElementById(k).value.trim();t.code=t.code.toUpperCase();if(!t.code||!t.name||!t.start||!t.end||t.start>=t.end)return alert('Dữ liệu không hợp lệ');if(edit<0&&data.templates.some(x=>x.code===t.code))return alert('Code đã tồn tại');t.active=edit>=0?data.templates[edit].active:true;if(edit>=0)data.templates[edit]=t;else data.templates.push(t);edit=-1;persist();renderTemplates()}document.getElementById('week').addEventListener('change',renderStatus);renderWeeks();renderTemplates();